DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- Delete existing CAM 14 if any
    DELETE FROM public.topics WHERE name = 'CAM 14' AND user_id IS NULL;
    
    -- Insert CAM 14 topic
    VALUES (gen_random_uuid(), NULL, 'CAM 14', 'school', 'CAM', NOW() + interval '4 seconds')
    RETURNING id INTO v_topic_id;
    
END $$;